import { useState, useCallback } from "react";
import { GripVertical } from "lucide-react";

// ─── Types ───────────────────────────────────────────────────────────────────

export interface KanbanCandidate {
  id: string;
  name: string;
  score: number;
  stage: string;
  email?: string | null;
}

interface KanbanCardProps {
  candidate: KanbanCandidate;
  onDragStart: (e: React.DragEvent, candidateId: string) => void;
}

interface KanbanColumnProps {
  stage: string;
  candidates: KanbanCandidate[];
  onDragStart: (e: React.DragEvent, candidateId: string) => void;
  onDragOver: (e: React.DragEvent, stage: string) => void;
  onDragLeave: () => void;
  onDrop: (e: React.DragEvent, stage: string) => void;
  isDragOver: boolean;
}

interface KanbanBoardProps {
  jobId: string;
  candidates: KanbanCandidate[];
  onStageChange: (candidateId: string, newStage: string) => void;
  stages: string[];
}

// ─── Stage Styling ───────────────────────────────────────────────────────────

const STAGE_CONFIG: Record<
  string,
  { label: string; header: string; card: string; badge: string }
> = {
  applied: {
    label: "Applied",
    header:
      "bg-slate-100 text-slate-700 dark:bg-slate-800/60 dark:text-slate-300",
    card: "border-slate-200 dark:border-slate-700",
    badge:
      "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400",
  },
  screened: {
    label: "Screened",
    header:
      "bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300",
    card: "border-blue-200 dark:border-blue-800",
    badge:
      "bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400",
  },
  interview: {
    label: "Interview",
    header:
      "bg-violet-100 text-violet-700 dark:bg-violet-900/40 dark:text-violet-300",
    card: "border-violet-200 dark:border-violet-800",
    badge:
      "bg-violet-100 text-violet-600 dark:bg-violet-900/30 dark:text-violet-400",
  },
  offer: {
    label: "Offer",
    header:
      "bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300",
    card: "border-amber-200 dark:border-amber-800",
    badge:
      "bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400",
  },
  hired: {
    label: "Hired",
    header:
      "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300",
    card: "border-emerald-200 dark:border-emerald-800",
    badge:
      "bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400",
  },
  rejected: {
    label: "Rejected",
    header:
      "bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300",
    card: "border-red-200 dark:border-red-800",
    badge:
      "bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400",
  },
};

function getStageConfig(stage: string) {
  return (
    STAGE_CONFIG[stage] ?? {
      label: stage.charAt(0).toUpperCase() + stage.slice(1),
      header: "bg-muted text-muted-foreground",
      card: "border-border",
      badge: "bg-muted text-muted-foreground",
    }
  );
}

function getScoreColor(score: number): string {
  if (score >= 80) return "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400";
  if (score >= 60) return "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400";
  return "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400";
}

// ─── KanbanCard ──────────────────────────────────────────────────────────────

function KanbanCard({ candidate, onDragStart }: KanbanCardProps) {
  const scoreColor = getScoreColor(candidate.score);

  return (
    <div
      draggable
      onDragStart={(e) => onDragStart(e, candidate.id)}
      className="group bg-card border border-border rounded-md px-3 py-2.5 cursor-grab active:cursor-grabbing shadow-sm hover:shadow-md transition-shadow duration-150 select-none"
    >
      <div className="flex items-start gap-2">
        <GripVertical className="h-4 w-4 text-muted-foreground/40 group-hover:text-muted-foreground/70 shrink-0 mt-0.5 transition-colors" />
        <div className="flex-1 min-w-0">
          <p className="text-sm font-semibold text-foreground truncate leading-tight">
            {candidate.name}
          </p>
          {candidate.email && (
            <p className="text-[11px] text-muted-foreground truncate mt-0.5">
              {candidate.email}
            </p>
          )}
        </div>
        {candidate.score > 0 && (
          <span
            className={`shrink-0 text-[11px] font-semibold px-1.5 py-0.5 rounded ${scoreColor}`}
          >
            {Math.round(candidate.score)}%
          </span>
        )}
      </div>
    </div>
  );
}

// ─── KanbanColumn ─────────────────────────────────────────────────────────────

function KanbanColumn({
  stage,
  candidates,
  onDragStart,
  onDragOver,
  onDragLeave,
  onDrop,
  isDragOver,
}: KanbanColumnProps) {
  const config = getStageConfig(stage);

  return (
    <div className="flex flex-col min-w-[220px] w-[220px] shrink-0">
      {/* Column header */}
      <div
        className={`flex items-center justify-between px-3 py-2 rounded-t-lg ${config.header}`}
      >
        <span className="text-xs font-semibold uppercase tracking-wide">
          {config.label}
        </span>
        <span
          className={`text-[11px] font-semibold px-1.5 py-0.5 rounded-full ${config.badge}`}
        >
          {candidates.length}
        </span>
      </div>

      {/* Drop zone */}
      <div
        className={`flex-1 min-h-[120px] rounded-b-lg border border-t-0 transition-all duration-150 ${config.card} ${
          isDragOver
            ? "border-dashed border-2 bg-primary/5 scale-[1.01]"
            : "bg-muted/20"
        }`}
        onDragOver={(e) => onDragOver(e, stage)}
        onDragLeave={onDragLeave}
        onDrop={(e) => onDrop(e, stage)}
      >
        <div className="p-2 space-y-2">
          {candidates.length === 0 ? (
            <p className="text-[11px] text-muted-foreground text-center py-4 italic">
              No candidates
            </p>
          ) : (
            candidates.map((candidate) => (
              <KanbanCard
                key={candidate.id}
                candidate={candidate}
                onDragStart={onDragStart}
              />
            ))
          )}
        </div>
      </div>
    </div>
  );
}

// ─── KanbanBoard ─────────────────────────────────────────────────────────────

export default function KanbanBoard({
  candidates,
  onStageChange,
  stages,
}: KanbanBoardProps) {
  const [dragOverColumn, setDragOverColumn] = useState<string | null>(null);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  const handleDragStart = useCallback(
    (e: React.DragEvent, candidateId: string) => {
      setDraggingId(candidateId);
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("candidateId", candidateId);
    },
    []
  );

  const handleDragOver = useCallback(
    (e: React.DragEvent, stage: string) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      setDragOverColumn(stage);
    },
    []
  );

  const handleDragLeave = useCallback(() => {
    setDragOverColumn(null);
  }, []);

  const handleDrop = useCallback(
    (e: React.DragEvent, targetStage: string) => {
      e.preventDefault();
      setDragOverColumn(null);
      const candidateId = e.dataTransfer.getData("candidateId");
      if (!candidateId) return;

      const candidate = candidates.find((c) => c.id === candidateId);
      if (!candidate) return;
      if (candidate.stage === targetStage) return;

      onStageChange(candidateId, targetStage);
      setDraggingId(null);
    },
    [candidates, onStageChange]
  );

  // Group candidates by stage
  const grouped = stages.reduce<Record<string, KanbanCandidate[]>>(
    (acc, stage) => {
      acc[stage] = candidates.filter((c) => c.stage === stage);
      return acc;
    },
    {}
  );

  // Candidates whose stage doesn't match any known column fall into "applied"
  const knownStages = new Set(stages);
  candidates.forEach((c) => {
    if (!knownStages.has(c.stage)) {
      grouped["applied"] = [...(grouped["applied"] ?? []), c];
    }
  });

  return (
    <div
      className="overflow-x-auto pb-4"
      onDragEnd={() => {
        setDragOverColumn(null);
        setDraggingId(null);
      }}
    >
      <div className="flex gap-3 min-w-max">
        {stages.map((stage) => (
          <KanbanColumn
            key={stage}
            stage={stage}
            candidates={grouped[stage] ?? []}
            onDragStart={handleDragStart}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            isDragOver={dragOverColumn === stage && draggingId !== null}
          />
        ))}
      </div>
    </div>
  );
}

import { useState, useRef, useCallback } from "react";
import { Upload, FileText, CheckCircle2, XCircle, Loader2, X, RefreshCw } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";

// ─── Types ───────────────────────────────────────────────────────────────────

type FileStatus = "pending" | "uploading" | "done" | "failed";

interface FileEntry {
  file: File;
  status: FileStatus;
  error?: string;
}

interface BulkUploadZoneProps {
  jobId: string;
  userId: string;
  onUploadComplete: () => void;
  maxFiles?: number;
  maxFileSize?: number; // MB
  disabled?: boolean;
}

const ACCEPTED_TYPES = [
  "application/pdf",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/msword",
  "application/rtf",
  "text/plain",
];

const ACCEPTED_EXTENSIONS = ".pdf,.docx,.doc,.rtf,.txt";
const CONCURRENCY = 5;

// ─── Component ───────────────────────────────────────────────────────────────

export default function BulkUploadZone({
  jobId,
  userId,
  onUploadComplete,
  maxFiles = 200,
  maxFileSize = 5,
  disabled = false,
}: BulkUploadZoneProps) {
  const [entries, setEntries] = useState<FileEntry[]>([]);
  const [dragOver, setDragOver] = useState(false);
  const [uploading, setUploading] = useState(false);
  const cancelRef = useRef(false);

  const updateEntry = useCallback(
    (index: number, patch: Partial<FileEntry>) => {
      setEntries((prev) =>
        prev.map((e, i) => (i === index ? { ...e, ...patch } : e))
      );
    },
    []
  );

  const addFiles = useCallback(
    (newFiles: File[]) => {
      const valid: File[] = [];
      for (const f of newFiles) {
        if (!ACCEPTED_TYPES.includes(f.type) && !f.name.match(/\.(pdf|docx|doc|rtf|txt)$/i)) {
          toast.error(`${f.name}: unsupported file type`);
          continue;
        }
        if (f.size > maxFileSize * 1024 * 1024) {
          toast.error(`${f.name}: exceeds ${maxFileSize}MB limit`);
          continue;
        }
        valid.push(f);
      }

      setEntries((prev) => {
        const existingNames = new Set(prev.map((e) => e.file.name.toLowerCase()));
        const toAdd: FileEntry[] = [];
        for (const f of valid) {
          if (existingNames.has(f.name.toLowerCase())) continue;
          if (prev.length + toAdd.length >= maxFiles) {
            toast.error(`Maximum ${maxFiles} files allowed`);
            break;
          }
          existingNames.add(f.name.toLowerCase());
          toAdd.push({ file: f, status: "pending" });
        }
        return [...prev, ...toAdd];
      });
    },
    [maxFiles, maxFileSize]
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setDragOver(false);
      if (disabled || uploading) return;
      addFiles(Array.from(e.dataTransfer.files));
    },
    [disabled, uploading, addFiles]
  );

  const handleFileSelect = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files) {
        addFiles(Array.from(e.target.files));
        e.target.value = "";
      }
    },
    [addFiles]
  );

  const uploadSingle = async (
    entry: FileEntry,
    index: number
  ): Promise<boolean> => {
    if (cancelRef.current) return false;

    updateEntry(index, { status: "uploading" });

    try {
      const filePath = `${userId}/${jobId}/${Date.now()}_${entry.file.name}`;

      const { error: uploadError } = await supabase.storage
        .from("resumes")
        .upload(filePath, entry.file);

      if (uploadError) throw new Error(uploadError.message);
      if (cancelRef.current) return false;

      const { error: insertError } = await (supabase as any)
        .from("resumes")
        .insert({
          job_id: jobId,
          filename: entry.file.name,
          file_path: filePath,
        });

      if (insertError) {
        // If insert fails, clean up storage
        await supabase.storage.from("resumes").remove([filePath]).catch(() => {});
        throw new Error(insertError.message);
      }

      updateEntry(index, { status: "done" });
      return true;
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Upload failed";
      updateEntry(index, { status: "failed", error: message });
      return false;
    }
  };

  const runQueue = async (entriesToProcess: FileEntry[]) => {
    cancelRef.current = false;
    setUploading(true);

    // Get indexes of pending entries in the current state snapshot
    // We need stable indexes from the full entries array
    const pendingIndexes: number[] = [];
    setEntries((prev) => {
      prev.forEach((e, i) => {
        if (e.status === "pending") pendingIndexes.push(i);
      });
      return prev;
    });

    // Process in batches of CONCURRENCY
    let i = 0;
    const total = pendingIndexes.length;
    let doneCount = 0;
    let failCount = 0;

    while (i < total && !cancelRef.current) {
      const batch = pendingIndexes.slice(i, i + CONCURRENCY);

      // Snapshot current entries to pass to uploadSingle
      let currentEntries: FileEntry[] = [];
      setEntries((prev) => { currentEntries = prev; return prev; });

      const results = await Promise.all(
        batch.map((idx) => uploadSingle(currentEntries[idx], idx))
      );

      results.forEach((ok) => {
        if (ok) doneCount++;
        else failCount++;
      });

      i += CONCURRENCY;
    }

    setUploading(false);

    if (cancelRef.current) {
      toast.error("Upload cancelled");
      return;
    }

    if (doneCount > 0 && failCount === 0) {
      toast.success(`${doneCount} resume${doneCount !== 1 ? "s" : ""} uploaded`);
      onUploadComplete();
    } else if (doneCount > 0 && failCount > 0) {
      toast.error(`${doneCount} uploaded, ${failCount} failed`);
      onUploadComplete();
    } else {
      toast.error("All uploads failed");
    }
  };

  const handleStartUpload = () => {
    const pending = entries.filter((e) => e.status === "pending");
    if (pending.length === 0) {
      toast.error("No files to upload");
      return;
    }
    runQueue(pending);
  };

  const handleCancel = () => {
    cancelRef.current = true;
  };

  const handleRetry = useCallback((index: number) => {
    setEntries((prev) =>
      prev.map((e, i) =>
        i === index ? { ...e, status: "pending", error: undefined } : e
      )
    );
  }, []);

  const handleRemove = useCallback((index: number) => {
    setEntries((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const handleRetryAll = () => {
    setEntries((prev) =>
      prev.map((e) =>
        e.status === "failed" ? { ...e, status: "pending", error: undefined } : e
      )
    );
  };

  const doneCount = entries.filter((e) => e.status === "done").length;
  const failedCount = entries.filter((e) => e.status === "failed").length;
  const uploadingCount = entries.filter((e) => e.status === "uploading").length;
  const pendingCount = entries.filter((e) => e.status === "pending").length;
  const totalCount = entries.length;
  const progressPct = totalCount > 0 ? Math.round((doneCount / totalCount) * 100) : 0;

  return (
    <div className="space-y-3">
      {/* Drop zone */}
      <div
        className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-all duration-200 flex flex-col items-center justify-center ${
          disabled || uploading
            ? "opacity-50 cursor-not-allowed border-border"
            : dragOver
            ? "border-primary bg-primary/5 scale-[1.01]"
            : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
        }`}
        onDragOver={(e) => {
          e.preventDefault();
          if (!disabled && !uploading) setDragOver(true);
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        onClick={() => {
          if (disabled || uploading) return;
          document.getElementById("bulk-file-input")?.click();
        }}
      >
        <div className="w-12 h-12 rounded-xl bg-muted flex items-center justify-center mb-3">
          <Upload className="h-6 w-6 text-primary" />
        </div>
        <p className="text-sm font-medium text-foreground mb-1">
          Drop up to {maxFiles} resumes here
        </p>
        <p className="text-xs text-muted-foreground">
          PDF, DOCX, DOC, RTF, TXT · {maxFileSize}MB each
        </p>
        <input
          id="bulk-file-input"
          type="file"
          className="hidden"
          multiple
          accept={ACCEPTED_EXTENSIONS}
          onChange={handleFileSelect}
          disabled={disabled || uploading}
        />
      </div>

      {/* File list */}
      {entries.length > 0 && (
        <>
          <div className="border border-border rounded-lg overflow-hidden">
            {/* List header */}
            <div className="flex items-center justify-between px-3 py-2 bg-muted/40 border-b border-border">
              <span className="text-xs font-medium text-muted-foreground">
                {totalCount} file{totalCount !== 1 ? "s" : ""}
                {doneCount > 0 && ` · ${doneCount} done`}
                {failedCount > 0 && ` · ${failedCount} failed`}
                {uploadingCount > 0 && ` · ${uploadingCount} uploading`}
              </span>
              {failedCount > 0 && !uploading && (
                <button
                  onClick={handleRetryAll}
                  className="text-xs text-primary hover:text-primary/80 transition-colors flex items-center gap-1"
                >
                  <RefreshCw className="h-3 w-3" />
                  Retry all failed
                </button>
              )}
            </div>

            {/* Scrollable file rows */}
            <div className="max-h-[300px] overflow-y-auto divide-y divide-border">
              {entries.map((entry, index) => (
                <div
                  key={`${entry.file.name}-${index}`}
                  className="flex items-center gap-2 px-3 py-2"
                >
                  {/* Status icon */}
                  <div className="shrink-0">
                    {entry.status === "done" && (
                      <CheckCircle2 className="h-4 w-4 text-emerald-500" />
                    )}
                    {entry.status === "failed" && (
                      <XCircle className="h-4 w-4 text-destructive" />
                    )}
                    {entry.status === "uploading" && (
                      <Loader2 className="h-4 w-4 text-primary animate-spin" />
                    )}
                    {entry.status === "pending" && (
                      <FileText className="h-4 w-4 text-muted-foreground" />
                    )}
                  </div>

                  {/* Filename + error */}
                  <div className="flex-1 min-w-0">
                    <p
                      className={`text-xs truncate ${
                        entry.status === "done"
                          ? "text-muted-foreground"
                          : entry.status === "failed"
                          ? "text-destructive"
                          : "text-foreground"
                      }`}
                    >
                      {entry.file.name}
                    </p>
                    {entry.error && (
                      <p className="text-[11px] text-destructive truncate">
                        {entry.error}
                      </p>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="shrink-0 flex items-center gap-1">
                    {entry.status === "failed" && !uploading && (
                      <button
                        onClick={() => handleRetry(index)}
                        className="text-xs text-primary hover:text-primary/80 transition-colors"
                        title="Retry"
                      >
                        <RefreshCw className="h-3.5 w-3.5" />
                      </button>
                    )}
                    {(entry.status === "pending" || entry.status === "failed") &&
                      !uploading && (
                        <button
                          onClick={() => handleRemove(index)}
                          className="text-muted-foreground hover:text-foreground transition-colors"
                          title="Remove"
                        >
                          <X className="h-3.5 w-3.5" />
                        </button>
                      )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Progress bar — only visible during upload */}
          {uploading && (
            <div className="space-y-1.5">
              <div className="flex items-center justify-between text-xs text-muted-foreground">
                <span>
                  {doneCount} / {totalCount} uploaded
                </span>
                <span>{progressPct}%</span>
              </div>
              <Progress value={progressPct} className="h-2" />
            </div>
          )}

          {/* Action row */}
          <div className="flex items-center gap-2">
            {!uploading ? (
              <>
                <Button
                  size="sm"
                  className="gap-1.5"
                  onClick={handleStartUpload}
                  disabled={pendingCount === 0 && failedCount === 0}
                >
                  <Upload className="h-4 w-4" />
                  Upload {pendingCount > 0 ? pendingCount : failedCount} File
                  {(pendingCount > 1 || failedCount > 1) ? "s" : ""}
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-muted-foreground"
                  onClick={() => setEntries([])}
                >
                  Clear all
                </Button>
              </>
            ) : (
              <Button
                variant="outline"
                size="sm"
                className="gap-1.5 text-destructive hover:text-destructive"
                onClick={handleCancel}
              >
                <X className="h-4 w-4" />
                Cancel
              </Button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

